-- Fictional legacy records for full relationship/adoption tests. No production data.
CREATE VIEW public.suppliers_supplier AS SELECT * FROM jsonb_to_record('{"id": 7, "owner_id": 42, "trade_name": "Legacy bakery", "legal_name": "", "tax_id": "fictional-tax", "business_type": "bakery", "contact_email": "legacy@example.test", "contact_phone": "fictional-phone", "standing": "active", "financial_eligibility": "disabled", "rejection_reason": "", "reapplication_conditions": "", "warning_reason": "", "suspension_reason": "", "suspension_review_date": null, "closure_reason": "", "closure_date": null, "created_at": "2026-10-09T12:00:00Z", "updated_at": "2026-10-09T12:00:00Z"}'::jsonb) AS legacy(id bigint, owner_id bigint, trade_name text, legal_name text, tax_id text, business_type text, contact_email text, contact_phone text, standing text, financial_eligibility text, rejection_reason text, reapplication_conditions text, warning_reason text, suspension_reason text, suspension_review_date text, closure_reason text, closure_date text, created_at text, updated_at text);
CREATE VIEW public.suppliers_establishment AS SELECT * FROM jsonb_to_record('{"id": 8, "supplier_id": 7, "name": "Legacy site", "description": "", "is_active": true, "created_at": "2026-10-09T12:00:00Z", "updated_at": "2026-10-09T12:00:00Z"}'::jsonb) AS legacy(id bigint, supplier_id bigint, name text, description text, is_active boolean, created_at text, updated_at text);
CREATE VIEW public.suppliers_pickuppoint AS SELECT * FROM jsonb_to_record('{"id": 9, "establishment_id": 8, "name": "Legacy pickup", "address_street": "Legacy street", "address_number": "1", "address_complement": "", "address_neighborhood": "Center", "address_city": "City", "address_state": "MT", "address_postal_code": "123", "time_zone": "America/Cuiaba", "latitude": -15.601234, "longitude": -56.091234, "approx_latitude": -15.6, "approx_longitude": -56.09, "access_instructions": "Private instructions", "service_intervals": [], "is_private_address": true, "version": 1, "is_active": true, "created_at": "2026-10-09T12:00:00Z", "updated_at": "2026-10-09T12:00:00Z"}'::jsonb) AS legacy(id bigint, establishment_id bigint, name text, address_street text, address_number text, address_complement text, address_neighborhood text, address_city text, address_state text, address_postal_code text, time_zone text, latitude numeric, longitude numeric, approx_latitude numeric, approx_longitude numeric, access_instructions text, service_intervals jsonb, is_private_address boolean, version bigint, is_active boolean, created_at text, updated_at text);
CREATE VIEW public.suppliers_event AS SELECT * FROM jsonb_to_record('{"id": 10, "supplier_id": 7, "actor_id": 42, "event_type": "supplier_registered", "prior_standing": "", "resulting_standing": "pending_approval", "reason": "Legacy registration", "evidence": "", "metadata": {}, "created_at": "2026-10-09T12:00:00Z"}'::jsonb) AS legacy(id bigint, supplier_id bigint, actor_id bigint, event_type text, prior_standing text, resulting_standing text, reason text, evidence text, metadata jsonb, created_at text);
CREATE VIEW public.suppliers_pickuppoint_history AS SELECT * FROM jsonb_to_record('{"id": 11, "pickup_point_id": 9, "version": 1, "actor_id": 42, "snapshot": {"name": "Legacy pickup", "version": 1, "establishment_id": 8}, "change_reason": "Initial creation.", "created_at": "2026-10-09T12:00:00Z"}'::jsonb) AS legacy(id bigint, pickup_point_id bigint, version bigint, actor_id bigint, snapshot jsonb, change_reason text, created_at text);
CREATE VIEW public.identity_token AS SELECT * FROM jsonb_to_record('{"id": 12, "user_id": 42, "token_hash": "fixture-hash-not-a-real-token", "purpose": "email_verification", "expires_at": "2026-10-09T12:00:00Z", "is_used": false, "used_at": null, "created_at": "2026-10-09T12:00:00Z"}'::jsonb) AS legacy(id bigint, user_id bigint, token_hash text, purpose text, expires_at text, is_used boolean, used_at text, created_at text);
CREATE VIEW public.identity_login_attempt AS SELECT * FROM jsonb_to_record('{"id": 13, "identifier": "legacy@example.test", "ip_address": "127.0.0.1", "successful": false, "attempt_time": "2026-10-09T12:00:00Z"}'::jsonb) AS legacy(id bigint, identifier text, ip_address text, successful boolean, attempt_time text);
CREATE VIEW public.common_audit_fact AS SELECT * FROM jsonb_to_record('{"id": "019535d9-3df7-79fb-b466-fa907fa17f9e", "entity_type": "supplier", "entity_id": "7", "actor_id": 42, "action": "registered", "authority_or_policy": "legacy-policy", "payload": {"safe": 1}}'::jsonb) AS legacy(id text, entity_type text, entity_id text, actor_id bigint, action text, authority_or_policy text, payload jsonb);
CREATE VIEW public.common_outbox_message AS SELECT * FROM jsonb_to_record('{"id": "019535d9-3df7-79fb-b466-fa907fa17f9f", "topic": "test-events", "event_type": "supplier_registered", "payload": {"supplier_id": 7}, "headers": {}, "status": "pending", "scheduled_for": "2026-10-09T12:00:00Z", "processed_at": null, "attempts": 0, "last_error": "", "idempotency_key": null, "created_at": "2026-10-09T12:00:00Z"}'::jsonb) AS legacy(id text, topic text, event_type text, payload jsonb, headers jsonb, status text, scheduled_for text, processed_at text, attempts bigint, last_error text, idempotency_key text, created_at text);
CREATE VIEW public.common_idempotency_record AS SELECT * FROM jsonb_to_record('{"id": "019535d9-3df7-79fb-b466-fa907fa17f90", "actor_identifier": "user:42", "command_name": "legacy-register", "idempotency_key": "old-request", "input_digest": "fixture-digest", "status": "committed", "result_code": 201, "response_payload": {"id": 7}, "created_at": "2026-10-09T12:00:00Z"}'::jsonb) AS legacy(id text, actor_identifier text, command_name text, idempotency_key text, input_digest text, status text, result_code bigint, response_payload jsonb, created_at text);
